// Build Slack Block Kit message for human approval.
// Reads from $('When Executed by Another Workflow') because SF Upsert above
// REPLACES $json with its API response (just the created record id).

const j = $('When Executed by Another Workflow').first().json;
const SF_BASE = 'https://por.my.salesforce.com';

// Format SF links if records found
const leadLink = j.found_lead_id ? `${SF_BASE}/${j.found_lead_id}` : null;
const contactLink = j.found_contact_id ? `${SF_BASE}/${j.found_contact_id}` : null;
const accountLink = j.found_account_id ? `${SF_BASE}/${j.found_account_id}` : null;

// SF status summary
let sfStatus;
if (j.found_lead_id) {
  sfStatus = `🟡 Existing Lead found: <${leadLink}|${j.found_lead_id}>`;
} else if (j.found_contact_id) {
  const acctStr = accountLink ? ` (Account: <${accountLink}|${j.found_account_status || 'Unknown'}>)` : '';
  sfStatus = `🟢 Existing Contact found: <${contactLink}|${j.found_contact_id}>${acctStr}`;
} else {
  sfStatus = '🆕 *No Salesforce match* — new lead';
}

// Lead detail block
const details = [];
if (j.formattedFirst || j.formattedLast) details.push(`*Name:* ${[j.formattedFirst, j.formattedLast].filter(Boolean).join(' ')}`);
if (j.formattedEmail) details.push(`*Email:* ${j.formattedEmail}`);
if (j.formattedCompany) details.push(`*Company:* ${j.formattedCompany}`);
if (j.formattedCountry) details.push(`*Country:* ${j.formattedCountry}`);
if (j.phone) details.push(`*Phone:* ${j.phone}`);
if (j.formattedIndustry) details.push(`*Industry:* ${j.formattedIndustry}`);
if (j.WPFormName) details.push(`*Form:* ${j.WPFormName}`);
if (j.utmsource) details.push(`*UTM source:* ${j.utmsource}`);
if (j.utmCampaign) details.push(`*UTM campaign:* ${j.utmCampaign}`);
if (j.LandingPage || j.landingPage) details.push(`*Landing:* ${j.LandingPage || j.landingPage}`);

const detailText = details.join('\n') || '_(no detail fields populated)_';

// Buttons embed resumeUrl with decision query param.
// resumeUrl already includes ?signature=... so we must APPEND with &, not ?.
const resumeBase = $execution.resumeUrl;
const sep = resumeBase.includes('?') ? '&' : '?';
const hashParam = encodeURIComponent(j.Idempotency_Hash__c || '');
const continueUrl = `${resumeBase}${sep}decision=continue&hash=${hashParam}`;
const killUrl = `${resumeBase}${sep}decision=kill&hash=${hashParam}`;

const blocks = [
  {
    type: 'header',
    text: { type: 'plain_text', text: '🌍 Africa lead — human triage required', emoji: true }
  },
  {
    type: 'section',
    text: { type: 'mrkdwn', text: sfStatus }
  },
  {
    type: 'section',
    text: { type: 'mrkdwn', text: detailText }
  },
  {
    type: 'context',
    elements: [
      { type: 'mrkdwn', text: `Submission: \`${j.Idempotency_Hash__c}\` · Source: \`${j.source}\` · n8n exec: \`${$execution.id}\`` }
    ]
  },
  {
    type: 'actions',
    elements: [
      {
        type: 'button',
        style: 'primary',
        text: { type: 'plain_text', text: '✅ Continue to MQL + routing', emoji: true },
        url: continueUrl,
        action_id: 'africa_continue'
      },
      {
        type: 'button',
        style: 'danger',
        text: { type: 'plain_text', text: '🛑 Kill (do not route)', emoji: true },
        url: killUrl,
        action_id: 'africa_kill'
      }
    ]
  }
];

const fallbackText = `Africa lead triage required: ${j.formattedFirst || ''} ${j.formattedLast || ''} from ${j.formattedCompany || j.formattedEmail || 'unknown'}`;

return [{
  json: {
    ...j,
    slack_blocks: blocks,
    slack_fallback_text: fallbackText,
    continue_url: continueUrl,
    kill_url: killUrl
  }
}];

