parameters.jsCode:
// After Wait resumes, the query string from the click is on $json (from the GET hit).
// We also have access to the pre-wait payload via $('Code: Build Slack Block Kit message').first().json.

const preWaitPayload = $('Code: Build Slack Block Kit message').first().json;
const resumeQuery = $json;
const decision = (resumeQuery.decision || resumeQuery.query?.decision || '').toLowerCase();
const hashFromQuery = resumeQuery.hash || resumeQuery.query?.hash;

// Defense: confirm hash matches (anti-CSRF light — anyone with the URL can hit it,
// but the URL was only sent to Dean+Kirk DMs so attack surface is small).
if (hashFromQuery && hashFromQuery !== preWaitPayload.Idempotency_Hash__c) {
  throw new Error(`Hash mismatch: query=${hashFromQuery} pre-wait=${preWaitPayload.Idempotency_Hash__c}`);
}

if (decision !== 'continue' && decision !== 'kill') {
  throw new Error(`Invalid decision: "${decision}". Expected 'continue' or 'kill'.`);
}

// Slack user_id of the clicker isn't available from a plain url-button click.
// For audit we record the timestamp and the decision. Upgrade path: switch to
// proper Slack interactivity (chat.postMessage with action elements + Slack app
// signing secret verification) to capture user_id.
const decided_at = new Date().toISOString();

return [{
  json: {
    ...preWaitPayload,
    africa_decision: decision,
    africa_decided_at: decided_at,
    Status__c: decision === 'continue' ? 'africa_continued' : 'africa_killed'
  }
}];

